#include <vector>

class Solution {
public:
    bool hasTrailingZeros(std::vector<int>& nums) {
        int count = 0;
        for (int x : nums) {
            if ((x & 1) == 0) {
                if (++count >= 2) return true;
            }
        }
        return false;
    }
};

class Solution {
    public boolean hasTrailingZeros(int[] nums) {
        int count = 0;
        for (int x : nums) {
            if ((x & 1) == 0) {
                if (++count >= 2) return true;
            }
        }
        return false;
    }
}

var hasTrailingZeros = function(nums) {
    let count = 0;
    for (const x of nums) {
        if ((x & 1) === 0) {
            if (++count >= 2) return true;
        }
    }
    return false;
};
